"use strict";(self.webpackChunkmc_backend_docs=self.webpackChunkmc_backend_docs||[]).push([[581],{5610:e=>{e.exports=JSON.parse('{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Backend wiki","href":"/MC-Backend-Docs/","docId":"README","unlisted":false},{"type":"link","label":"How the framework works","href":"/MC-Backend-Docs/framework","docId":"framework","unlisted":false},{"type":"link","label":"rules.dsc","href":"/MC-Backend-Docs/rules","docId":"rules","unlisted":false},{"type":"link","label":"Gamerules","href":"/MC-Backend-Docs/gamerules","docId":"gamerules","unlisted":false},{"type":"link","label":"Player flags","href":"/MC-Backend-Docs/flags","docId":"flags","unlisted":false},{"type":"link","label":"Stats","href":"/MC-Backend-Docs/stats","docId":"stats","unlisted":false},{"type":"link","label":"Control effects (world-lock ops and Frontend templates)","href":"/MC-Backend-Docs/control-effects","docId":"control-effects","unlisted":false},{"type":"link","label":"Currencies","href":"/MC-Backend-Docs/currencies","docId":"currencies","unlisted":false},{"type":"link","label":"Analytics","href":"/MC-Backend-Docs/analytics","docId":"analytics","unlisted":false},{"type":"link","label":"Event receipts","href":"/MC-Backend-Docs/receipts","docId":"receipts","unlisted":false},{"type":"link","label":"API engine","href":"/MC-Backend-Docs/api","docId":"api","unlisted":false},{"type":"link","label":"Living entities","href":"/MC-Backend-Docs/living-entities","docId":"living-entities","unlisted":false},{"type":"link","label":"Entities","href":"/MC-Backend-Docs/entities","docId":"entities","unlisted":false},{"type":"link","label":"Mounts","href":"/MC-Backend-Docs/mounts","docId":"mounts","unlisted":false},{"type":"link","label":"Items and Item Skills","href":"/MC-Backend-Docs/items","docId":"items","unlisted":false},{"type":"link","label":"Vaults","href":"/MC-Backend-Docs/vaults","docId":"vaults","unlisted":false},{"type":"link","label":"Trade","href":"/MC-Backend-Docs/trades","docId":"trades","unlisted":false},{"type":"link","label":"In-game player wiki","href":"/MC-Backend-Docs/wiki","docId":"wiki","unlisted":false},{"type":"link","label":"Language","href":"/MC-Backend-Docs/language","docId":"language","unlisted":false},{"type":"link","label":"Loot","href":"/MC-Backend-Docs/loot","docId":"loot","unlisted":false},{"type":"link","label":"SkillMoves, classes, Global Build slots","href":"/MC-Backend-Docs/skills","docId":"skills","unlisted":false},{"type":"link","label":"Cosmetics and gear","href":"/MC-Backend-Docs/cosmetics","docId":"cosmetics","unlisted":false},{"type":"link","label":"Season pass","href":"/MC-Backend-Docs/season-pass","docId":"season-pass","unlisted":false},{"type":"link","label":"Titles / ChatPrefix","href":"/MC-Backend-Docs/titles","docId":"titles","unlisted":false},{"type":"link","label":"Chat","href":"/MC-Backend-Docs/chat","docId":"chat","unlisted":false},{"type":"link","label":"Quests","href":"/MC-Backend-Docs/quests","docId":"quests","unlisted":false},{"type":"link","label":"Travel","href":"/MC-Backend-Docs/travel","docId":"travel","unlisted":false},{"type":"link","label":"Skills, classes, NPCs, menus","href":"/MC-Backend-Docs/content-contracts","docId":"content-contracts","unlisted":false},{"type":"link","label":"Triggerables and Eventstats","href":"/MC-Backend-Docs/triggers","docId":"triggers","unlisted":false},{"type":"link","label":"Menus","href":"/MC-Backend-Docs/menus","docId":"menus","unlisted":false},{"type":"link","label":"HUD","href":"/MC-Backend-Docs/hud","docId":"hud","unlisted":false},{"type":"link","label":"Daily reset","href":"/MC-Backend-Docs/resets","docId":"resets","unlisted":false},{"type":"link","label":"Areas","href":"/MC-Backend-Docs/areas","docId":"areas","unlisted":false},{"type":"category","label":"Mechanics","collapsible":true,"collapsed":true,"customProps":{"description":"Targeting, context, requirements, and operations"},"items":[{"type":"link","label":"Mechanic targeting","href":"/MC-Backend-Docs/mechanics/targeting","docId":"mechanics/targeting","unlisted":false},{"type":"link","label":"Mechanic context","href":"/MC-Backend-Docs/mechanics/context","docId":"mechanics/context","unlisted":false},{"type":"link","label":"Mechanic requirements","href":"/MC-Backend-Docs/mechanics/requirements","docId":"mechanics/requirements","unlisted":false},{"type":"link","label":"Effect operations","href":"/MC-Backend-Docs/mechanics/operations","docId":"mechanics/operations","unlisted":false}],"href":"/MC-Backend-Docs/mechanics/"},{"type":"link","label":"Keeping this wiki honest","href":"/MC-Backend-Docs/maintaining","docId":"maintaining","unlisted":false}]},"docs":{"analytics":{"id":"analytics","title":"Analytics","description":"Live for currency and item obtain/spend counters, plus optional shop sink tags.","sidebar":"tutorialSidebar"},"api":{"id":"api","title":"API engine","description":"Live for the staff socket check. pirate-era-api is a shared Python process. Bounty posters are the first feature. Later scripts use the same host, port, and handshake. Host and port are in Backend rules.dsc. The token is not.","sidebar":"tutorialSidebar"},"areas":{"id":"areas","title":"Areas","description":"Live. Area Config templates, world instances, area groups, AreaRule checks, and optional categories.","sidebar":"tutorialSidebar"},"chat":{"id":"chat","title":"Chat","description":"Live as a prefix assembler and a message filter. Harvest: ChatColor.dsc AddChatPrefix stacked champion, yonko, crew, then family name. Chatmonitor.dsc blocked a word list, counted warnings, muted, and rejected a repeat message.","sidebar":"tutorialSidebar"},"content-contracts":{"id":"content-contracts","title":"Skills, classes, NPCs, menus","description":"SkillMoves, classes, and Global Build slots: skills.md. This page keeps prefixes that still have no engine.","sidebar":"tutorialSidebar"},"control-effects":{"id":"control-effects","title":"Control effects (world-lock ops and Frontend templates)","description":"Live. World locks are mechanic operations, same as PLAYSOUND. type: NOWALK runs a Backend task that zeros walk. It does not SET_STAT a matching stat id.","sidebar":"tutorialSidebar"},"cosmetics":{"id":"cosmetics","title":"Cosmetics and gear","description":"Live. Gear is items. Cosmetics are stands. Frontend may run both on one click. Backend does not spawn a stand because a gear id was set.","sidebar":"tutorialSidebar"},"currencies":{"id":"currencies","title":"Currencies","description":"Live. Frontend currency_* scripts are the registry. The engine does not pick a default currency.","sidebar":"tutorialSidebar"},"entities":{"id":"entities","title":"Entities","description":"Combat mobs and companions. Prefixes: entity, entityai, entityanimation, entitymodel, entityskill, entityprofile. Living HP and damage stay on livingentity. On the Frontend, one mob\'s entity, entityai, and entityskill containers share that mob\'s file (entityexampleboar.dsc). Profiles and living entities stay shared. See living-entities.md and content-contracts.md.","sidebar":"tutorialSidebar"},"flags":{"id":"flags","title":"Player flags","description":"Partial. Paths come from rules.dsc flag_saves. Getters and setters exist for stats, currencies, living-entity bind, language, triggerable bind, casting session, trigger cooldowns, SkillMove category bans, gear slot ids, cosmetic persist channels, season pass counters, vault slot maps, daily reset period stamps, and quest progress.","sidebar":"tutorialSidebar"},"framework":{"id":"framework","title":"How the framework works","description":"Live. Backend is the engine (tasks, procs, world events). Frontend is type: data configs. They share vocabulary through rules.dsc.","sidebar":"tutorialSidebar"},"gamerules":{"id":"gamerules","title":"Gamerules","description":"Live as pack-wide server policy. Frontend script registry_gamerules (rules.dsc pointer gamerules). Nested maps only.","sidebar":"tutorialSidebar"},"hud":{"id":"hud","title":"HUD","description":"Live for reload compile, cache assemble, persist layout, runtime overlays, and requirements plus presence ops.","sidebar":"tutorialSidebar"},"items":{"id":"items","title":"Items and Item Skills","description":"Partial. Create/give stamps display plus itemscript / level (and optional tier / set flags). Item Skills are itemskill* envelopes loaded by RUNITEMSKILL. Eat is Item Config consume: plus ONCONSUME. World click is a Frontend triggerable, same idea as SkillMove on hotbar. RepairProfile / LevelProfile YAML is still Contract. Spend itself is APPLY_TRANSACTION. Worn set-piece counting is not an engine.","sidebar":"tutorialSidebar"},"language":{"id":"language","title":"Language","description":"Live. Transcript scripts use prefix generaltranscript. Example: pirate-era-core-frontend/language/englishtranscript.dsc. Add generaltranscriptspanish (same keys) for a second language. Missing keys fall back to registrygamerules.language.default.","sidebar":"tutorialSidebar"},"living-entities":{"id":"living-entities","title":"Living entities","description":"Partial. Player bind and stat init work. Damage routing (APPLY / REDIRECT / SPLIT, conditions, OnSuccess / OnDeplete / OnFail) is Live. deal_damage is Live. Combat and resistance profiles use Vanilla Adjustifier FLAT + - * / on the vanilla intercept.","sidebar":"tutorialSidebar"},"loot":{"id":"loot","title":"Loot","description":"Partial / Live resolver. Prefixes loottable, lootpool, lootentry, lootcrate. Backend rolls those scripts and grants through grantlootresults. Party split is not in this engine.","sidebar":"tutorialSidebar"},"maintaining":{"id":"maintaining","title":"Keeping this wiki honest","description":"Update docs/ in the same change as the engine or rules.dsc. This folder is the option list. The architecture plan is the roadmap. Do not let them drift.","sidebar":"tutorialSidebar"},"mechanics/context":{"id":"mechanics/context","title":"Mechanic context","description":"Live. Keys are rules.dsc mechaniccontext. Build with buildmechaniccontext. Read with getmechanic_*. Do not hardcode field names.","sidebar":"tutorialSidebar"},"mechanics/operations":{"id":"mechanics/operations","title":"Effect operations","description":"Dispatcher: handlemechanicoperations in Mechanics/Core/mechanicutils.dsc. Each operations..type is a case. New ops get a file under Mechanics/Individualoperations/ and a case here.","sidebar":"tutorialSidebar"},"mechanics/README":{"id":"mechanics/README","title":"Mechanics","description":"Partial. Dispatcher, context, targeting, requirements, inherit, PLAYSOUND, PLAYEFFECT, APPLYVELOCITY, PROJECTILE, DASH, SPAWNNOTABLE, SPAWNHOLOGRAM, STARTGPS, STOPGPS, SHOWHUDPART, HIDEHUDPART, CLEARHUDPARTS, SETHUDLAYOUT, PLACESPRAY, OPENSPRAYMENU, OPENTITLEMENU, EQUIPTITLE, UNEQUIPTITLE, CLEARTITLES, OPENWIKIMENU, REVEALWIKILORE, EQUIPGEAR, CLEARGEAR, EQUIPCOSMETIC, CLEARCOSMETIC, SPAWNCOSMETIC, NARRATE, GIVEITEM, GRANTLOOT, STARTQUEST, ADVANCEQUEST, COMPLETEQUEST, GRANTSEASONXP, SETSEASONTRACK, REDEEMSEASONREWARD, OPENSEASONPASS, APPLYTRANSACTION, OPENLOOTCRATE, TELEPORT, TRAVELTOWAYPOINT, ITEMCOOLDOWN, SWING, DEALDAMAGE, world-lock ops (NOWALK, \u2026), MODIFYSTAT, MODIFYSTATLEVEL, OVERLAYSTATLEVEL, CLEARSTATOVERLAY, SETSTAT, TOGGLESTAT, RUNSKILLMOVE, RUNITEMSKILL, RUNMECHANIC, CASTVANILLAEFFECT, BANCATEGORY, OPENMENU, CLOSEMENU, OPENCONFIRM, OPENDIALOGUE, OPENTYPING, OPENSTORAGE, and OPEN_TRADE are Live. Other ops are missing.","sidebar":"tutorialSidebar"},"mechanics/requirements":{"id":"mechanics/requirements","title":"Mechanic requirements","description":"Live. Missing or empty requirements always pass. Unknown type values fail.","sidebar":"tutorialSidebar"},"mechanics/targeting":{"id":"mechanics/targeting","title":"Mechanic targeting","description":"Every effect-operation calls resolvemechanicoperationtargets. PLAYSOUND and MODIFYSTAT smoke: pirate-era-core-frontend/Mechanics/mechanicexamples.dsc.","sidebar":"tutorialSidebar"},"menus":{"id":"menus","title":"Menus","description":"Live for open, click, close, footer fakeitems, packet cancel, kinds, OPENMENU, CLOSEMENU, OPENCONFIRM, OPENDIALOGUE, and OPEN_TYPING.","sidebar":"tutorialSidebar"},"mounts":{"id":"mounts","title":"Mounts","description":"Live for the mount ops and the sit, quit, death, and reload save hooks. Mounts/ and the SUMMONMOUNT through SETMOUNTROW tasks read these keys. Area rule MOUNTSPEED_CAP is registered. none means no scale.","sidebar":"tutorialSidebar"},"quests":{"id":"quests","title":"Quests","description":"Live. Categories, quests, objective progress, complete mechanics, and loot entry rewards.","sidebar":"tutorialSidebar"},"README":{"id":"README","title":"Backend wiki","description":"Option catalog for the Denizen MMORPG backend (mc-denizen-core-backend). Frontend content lives in pirate-era-core-frontend. This folder is the living list of what the engine accepts. Host these .md files as a wiki later without rewriting them.","sidebar":"tutorialSidebar"},"receipts":{"id":"receipts","title":"Event receipts","description":"Live for TRADE inserts and staff /packreceipt. TRANSACTION is reserved for shops. Analytics counters stay numbers only. See analytics.md.","sidebar":"tutorialSidebar"},"resets":{"id":"resets","title":"Daily reset","description":"Live as one Backend scheduler plus Frontend dailyreset rows. Harvest00, wiped dailyreward, announced, wiped monthly pass, reset hourly replay, and granted login gifts.","sidebar":"tutorialSidebar"},"rules":{"id":"rules","title":"rules.dsc","description":"Live as the shared contract. File: rules.dsc. Read it with proc[getrulevalue].context[]. Never copy these strings into ops.","sidebar":"tutorialSidebar"},"season-pass":{"id":"season-pass","title":"Season pass","description":"Live. One Frontend seasonpass_ file per season. Backend stores counters and redeems through existing ops. XP sources are triggerables. The menu is PAGE or SCROLL.","sidebar":"tutorialSidebar"},"skills":{"id":"skills","title":"SkillMoves, classes, Global Build slots","description":"Partial. Cast is still RUNSKILLMOVE plus Frontend kind: REFERENCE slots. The envelope is categories, requirements, and Cost Component costs. There is no class engine and no second Backend cast runtime. Do not bind mechanic ids on stat_skillmove_.","sidebar":"tutorialSidebar"},"stats":{"id":"stats","title":"Stats","description":"Live for value, regen, consumable, affects, linear equation. Partial for combat-state regen (PAUSE/SLOWED), percent-loss on death, extra equations.","sidebar":"tutorialSidebar"},"titles":{"id":"titles","title":"Titles / ChatPrefix","description":"Live as a catalog, ordered persist lists, and chat paint. Word filter and crew/rank rows are not this page.","sidebar":"tutorialSidebar"},"trades":{"id":"trades","title":"Trade","description":"Live. Shared 54 chest, ready handshake, swap, cancel return. Not a gui: true wiki PAGE. Convert-money in legacy TradeSystem.dsc is already Cost Component (/withdraw). Counts stay analytics. Who/what/when is Mongo record_receipt TRADE. YAML /Trades/ is forbidden. See receipts.md and analytics.md.","sidebar":"tutorialSidebar"},"travel":{"id":"travel","title":"Travel","description":"Live. Waypoint Config plus TRAVELTOWAYPOINT. Paying uses Cost Component. Requirements use the same maps as mechanics.","sidebar":"tutorialSidebar"},"triggers":{"id":"triggers","title":"Triggerables and Eventstats","description":"Partial. Player-bound triggerable configs init on join. World events dispatch through fire_stat_event. Eventstat is a stat with stateventconfig. A SkillMove is a skillmove data script with mechanics. An Item Skill is an itemskill data script listed on an Item Config. Hotbar 1 with casting mode runs RUNSKILLMOVE on statskillmove_1.","sidebar":"tutorialSidebar"},"vaults":{"id":"vaults","title":"Vaults","description":"Live. Private pages persist on flagsaves.vaults. Shared banks are Denizen noted inventories plus vaultindex. Not gui: true info menus. Not a crew engine.","sidebar":"tutorialSidebar"},"wiki":{"id":"wiki","title":"In-game player wiki","description":"Live. Hub plus category PAGE menus. Backend indexes existing prefixes and builds lore on click. This is not docs/ (dev option catalog) and not a Discord or web wiki. There is no wiki_ runtime prefix.","sidebar":"tutorialSidebar"}}}')}}]);